//! 🧪️ Actual artifact Pair owners lend every JSON variant and keep exact source text backing.
use semio_os_store_codec_registry::native_snapshot::{OriginalArtifactPairFailure,OriginalArtifactPairCause};
use semio_os_spr::history::RetainedHistoryOpMetaFault;
use semio_framework_pack_json::JsonError;
use semio_framework_job_failure::{OriginalDomainProjection,OriginalDomainView as V,OriginalDomainFailure};
use semio_framework_value::{ValueError,ValueRefusalKind,Number,RetainedCloneGrant,retirement::controlled::ControlledRetirement};
fn error()->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,"original native 源".to_owned())}
fn close(error:OriginalArtifactPairFailure){let mut owner=ControlledRetirement::retain(error);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:4096};for _ in 0..100000{if owner.terminal_is_empty(){break}owner.step(grant).unwrap();}assert!(owner.terminal_is_empty());}
#[test]
fn every_history_json_variant_matches_the_closed_language_neutral_schema(){let f:serde_json::Value=serde_json::from_str(include_str!("🧪️fixtures/🔣️.json")).unwrap();let name=f["message"].as_str().unwrap();let values=[JsonError::Native(error()),JsonError::UnexpectedEof,JsonError::UnexpectedByte{found:0xe1,offset:73},JsonError::InvalidNumber(73),JsonError::InvalidEscape(73),JsonError::InvalidUnicodeEscape(73),JsonError::UnpairedSurrogate(73),JsonError::ControlCharacterInString{byte:0x17,offset:73},JsonError::InvalidUtf8,JsonError::TrailingData(73),JsonError::MaxDepthExceeded(73),JsonError::DuplicateMember{name:name.to_owned(),offset:73}];for(value,row)in values.into_iter().zip(f["json"].as_array().unwrap()){let pointer=match &value{JsonError::Native(v)=>Some(v.message.as_ptr()),JsonError::DuplicateMember{name,..}=>Some(name.as_ptr()),_=>None};let failure=OriginalArtifactPairFailure::from(RetainedHistoryOpMetaFault::Json(value));let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert!(matches!(failure.projection_view(&[]).unwrap(),V::IntrinsicObject(3)));for(index,key)in f["pair"].as_array().unwrap().iter().enumerate(){assert_eq!(failure.projection_key(&[],index).unwrap(),key.as_str().unwrap())}assert!(matches!(failure.projection_view(&[0,1,1]).unwrap(),V::IntrinsicObject(n)if n==row.as_array().unwrap().len()-1));for(index,key)in row.as_array().unwrap()[1..].iter().enumerate(){assert_eq!(failure.projection_key(&[0,1,1],index).unwrap(),key.as_str().unwrap())}assert!(matches!(failure.projection_view(&[0,1,1,0]).unwrap(),V::IntrinsicText(kind)if kind==row[0].as_str().unwrap()));match &failure.cause{OriginalArtifactPairCause::History(RetainedHistoryOpMetaFault::Json(JsonError::Native(_)))=>assert!(matches!(failure.projection_view(&[0,1,1,1,1]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==pointer.unwrap())),OriginalArtifactPairCause::History(RetainedHistoryOpMetaFault::Json(JsonError::DuplicateMember{..}))=>{assert!(matches!(failure.projection_view(&[0,1,1,1]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==pointer.unwrap()));assert!(matches!(failure.projection_view(&[0,1,1,2]).unwrap(),V::IntrinsicNumber(Number::UInt(73))))},_=>{}}assert!(matches!(failure.projection_view(&[2]).unwrap(),V::IntrinsicNull));assert!(failure.projection_key(&[0,1,1],row.as_array().unwrap().len()-1).is_err());assert_eq!(failure.domain_code(),"original.artifactPair");});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close(failure);}}
#[test]
fn pair_native_receiving_and_enclosing_receipt_are_distinct_original_owners(){let mut receiving=semio_framework_value_native_owned::OriginalReceivingPrimary::from(error());receiving.receipt_refusal=Some(error());let inner=receiving.receipt_refusal.as_ref().unwrap().message.as_ptr();let mut failure=OriginalArtifactPairFailure::from(receiving);failure.receipt_refusal=Some(error());let outer=failure.receipt_refusal.as_ref().unwrap().message.as_ptr();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{assert!(matches!(failure.projection_view(&[0,1,1,1]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==inner));assert!(matches!(failure.projection_view(&[2,1]).unwrap(),V::IntrinsicText(message)if message.as_ptr()==outer));assert_ne!(inner,outer);});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close(failure);}
